/// Writes every shipped file into `dir`, creating the directories it needs.
///
/// Subdirectories are part of the name — `palettes/azure-vivid.json` — and
/// `dist/fonts.css` reaches the faces at `../assets/fonts/`, so whatever
/// `dir` is, the fonts belong beside it and not inside it.
///
/// # Errors
///
/// Whatever the filesystem returns: a directory that cannot be created, a
/// file that cannot be written.
pub fn write_to(dir: impl AsRef<Path>) -> std::io::Result<()> {
    let dir = dir.as_ref();
    for (name, contents) in FILES {
        let path = dir.join(name);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(path, contents)?;
    }
    Ok(())
}
